#!/bin/bash
IFS=. read -r a b c d <<< "$1"; M=$((32 - $2)); N=$(( ((a<<24)|(b<<16)|(c<<8)|d) & (0xFFFFFFFF<<M) )); B=$(( N | ((1<<M)-1) )); F=$((N+1)); L=$((B-1)); printf "%d.%d.%d.%d - %d.%d.%d.%d" "$((F>>24 & 255))" "$((F>>16 & 255))" "$((F>>8 & 255))" "$((F & 255))" "$((L>>24 & 255))" "$((L>>16 & 255))" "$((L>>8 & 255))" "$((L & 255))"
